class FeeLedgerMember { protected String memberId; protected int monthlyFee; private int[] lateFeeHistory; private int feeCount; public FeeLedgerMember(String memberId, int monthlyFee) { this.memberId = memberId; this.monthlyFee = monthlyFee; lateFeeHistory = new int[10]; feeCount = 0; } protected void chargeLateFee(int amount) { if (feeCount < 10) { lateFeeHistory[feeCount] = amount; feeCount++; } } public int[] getLateFeeHistory() { int[] copy = new int[feeCount]; for (int i = 0; i < feeCount; i++) copy[i] = lateFeeHistory[i]; return copy; } public int getTotalLateFees() { int total = 0; for (int i = 0; i < feeCount; i++) total += lateFeeHistory[i]; return total; } }
class PremiumFeeLedgerMember extends FeeLedgerMember { public PremiumFeeLedgerMember(String memberId, int monthlyFee) { super(memberId, monthlyFee); } @Override protected void chargeLateFee(int amount) { super.chargeLateFee(amount / 2); } }
public class LateFeeLedger { public static void main(String[] args) { PremiumFeeLedgerMember p = new PremiumFeeLedgerMember("MEM5", 2000); p.chargeLateFee(200); System.out.println(p.getTotalLateFees()); int[] history = p.getLateFeeHistory(); history[0] = 999; System.out.println(p.getLateFeeHistory()[0]); } }